CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('customer','admin','super_admin');
CREATE TYPE application_status AS ENUM ('draft','submitted','under_review','information_requested','approved','rejected','withdrawn');
CREATE TYPE offer_status AS ENUM ('prepared','presented','accepted','declined','expired');
CREATE TYPE loan_status AS ENUM ('awaiting_disbursement','active','completed','cancelled');
CREATE TYPE transaction_status AS ENUM ('pending_verification','confirmed','rejected','reversed');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'customer',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_profiles(user_id uuid PRIMARY KEY REFERENCES users(id),name text NOT NULL,mobile text NOT NULL,date_of_birth date,guardian_name text,whatsapp text,address text,identifier_type text,identifier_encrypted text,consented_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),customer_id uuid NOT NULL REFERENCES users(id),status application_status NOT NULL DEFAULT 'draft',requested_amount_paise bigint,monthly_income_paise bigint,purpose text,next_of_kin jsonb,bank_snapshot jsonb,version int NOT NULL DEFAULT 1,submitted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX applications_customer_idx ON applications(customer_id); CREATE INDEX applications_status_idx ON applications(status,created_at);
CREATE TABLE witnesses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,position smallint NOT NULL CHECK(position IN(1,2)),details jsonb NOT NULL,UNIQUE(application_id,position));
CREATE TABLE documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,owner_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL,storage_key text NOT NULL,mime_type text NOT NULL,size_bytes int NOT NULL,scan_status text NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE application_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id),admin_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,message text,reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE offers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id),status offer_status NOT NULL DEFAULT 'prepared',terms jsonb NOT NULL,schedule_snapshot jsonb NOT NULL,total_interest_paise bigint NOT NULL,total_payable_paise bigint NOT NULL,prepared_by uuid NOT NULL REFERENCES users(id),presented_at timestamptz,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_live_offer ON offers(application_id) WHERE status IN ('prepared','presented','accepted');
CREATE TABLE loans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid UNIQUE NOT NULL REFERENCES applications(id),offer_id uuid UNIQUE NOT NULL REFERENCES offers(id),customer_id uuid NOT NULL REFERENCES users(id),status loan_status NOT NULL DEFAULT 'awaiting_disbursement',terms_snapshot jsonb NOT NULL,activated_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE instalments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),loan_id uuid NOT NULL REFERENCES loans(id),number int NOT NULL,due_date date NOT NULL,principal_paise bigint NOT NULL,interest_paise bigint NOT NULL,fees_paise bigint NOT NULL,total_due_paise bigint NOT NULL,UNIQUE(loan_id,number));
CREATE TABLE disbursements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),loan_id uuid NOT NULL REFERENCES loans(id),status transaction_status NOT NULL,amount_paise bigint NOT NULL,transfer_date date NOT NULL,bank_reference text NOT NULL,destination_snapshot jsonb NOT NULL,recorded_by uuid NOT NULL REFERENCES users(id),idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),loan_id uuid NOT NULL REFERENCES loans(id),status transaction_status NOT NULL DEFAULT 'pending_verification',amount_paise bigint NOT NULL,payment_date date NOT NULL,method text NOT NULL,reference text NOT NULL,recorded_by uuid NOT NULL REFERENCES users(id),idempotency_key text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz);
CREATE TABLE payment_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid NOT NULL REFERENCES payments(id),instalment_id uuid NOT NULL REFERENCES instalments(id),amount_paise bigint NOT NULL CHECK(amount_paise>0),UNIQUE(payment_id,instalment_id));
CREATE TABLE admin_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid REFERENCES applications(id),loan_id uuid REFERENCES loans(id),admin_id uuid NOT NULL REFERENCES users(id),note text NOT NULL,contact_channel text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id),entity_type text NOT NULL,entity_id text NOT NULL,action text NOT NULL,old_value jsonb,new_value jsonb,reason text,ip inet,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_entity_idx ON audit_events(entity_type,entity_id,created_at);
CREATE TABLE idempotency_keys(key text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),route text NOT NULL,response jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE password_reset_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,used_at timestamptz);
